// Valida Authorization: Bearer <SYNC_SECRET> si viene cabecera o si está configurado en n8n
const firstItem = $input.first().json;
const headers = firstItem.headers || {};
const auth = headers.authorization || headers.Authorization || firstItem.authorization || '';
const secret = ($env.SYNC_SECRET || '').trim();
if (secret && auth) {
  if (!auth.startsWith('Bearer ') || auth.slice(7).trim() !== secret) {
    throw new Error('Unauthorized');
  }
}
const body = firstItem.body || firstItem;
const url = String(body.url || body.q || body.modelId || '').trim();
if (!url) throw new Error('Missing url');
return [{ json: { url } }];

const urlOrId = String($input.item.json.url || '').trim();
let id = '';
const numMatch = urlOrId.match(/^#?(\d+)$/);
if (numMatch) {
  id = numMatch[1];
} else {
  const match = urlOrId.match(/(?:makerworld\.com\/[^\s]*\/models\/|models\/)(\d+)/i) || urlOrId.match(/(\d+)/);
  if (!match) throw new Error('Entrada no válida. Pon ID o URL.');
  id = match[1];
}
return { json: { externalId: id } };

const htmlStr = $input.item.json?.solution?.response || "";

// 1. Extraer contenido entre <pre> o <body>
let rawJson = htmlStr;
const preMatch = htmlStr.match(/<pre[^>]*>([\s\S]*?)<\/pre>/i);
if (preMatch) {
  rawJson = preMatch[1];
} else {
  const bodyMatch = htmlStr.match(/<body[^>]*>([\s\S]*?)<\/body>/i);
  if (bodyMatch) rawJson = bodyMatch[1];
}

// 2. Extraer estrictamente desde el primer '{' hasta el último '}'
const firstBrace = rawJson.indexOf('{');
const lastBrace = rawJson.lastIndexOf('}');
if (firstBrace !== -1 && lastBrace !== -1 && lastBrace > firstBrace) {
  rawJson = rawJson.substring(firstBrace, lastBrace + 1);
} else {
  rawJson = rawJson.replace(/^<pre[^>]*>/i, '').replace(/<\/pre>[\s\S]*$/i, '').trim();
}

try {
    const data = JSON.parse(rawJson);
    const instances = data.instances || [];
    if (!instances.length) throw new Error('No instances found.');

    const profiles = instances.map(ins => {
      const plates = ((ins.extention || {}).modelInfo || {}).plates || [];
      const platesGrams = plates.reduce((s, p) => s + (Number(p.weight) || 0), 0);
      const platesSeconds = plates.reduce((s, p) => s + (Number(p.prediction) || 0), 0);
      const grams = platesGrams || Number(ins.weight) || 0;
      const seconds = platesSeconds || Number(ins.prediction) || 0;
      return {
        id: String(ins.id || ins.profileId || ''),
        title: ins.title || ins.titleTranslated || 'Perfil sin nombre',
        name: ins.name || '',
        grams: Number.isFinite(grams) ? Number(grams.toFixed(2)) : 0,
        hours: Number.isFinite(seconds) ? Number((seconds / 3600).toFixed(3)) : 0,
        plateCount: plates.length || 1,
        isDefault: !!ins.isDefault,
        needAms: !!ins.needAms,
        colorCount: Number(ins.materialColorCnt) || Number(ins.materialCnt) || 1,
        cover: ins.cover || (ins.extention?.modelInfo?.plates?.[0]?.top_picture?.url) || null,
      };
    }).filter(p => p.grams > 0 || p.hours > 0);

    // Si hay múltiples perfiles que son partes de un ensamble, agregar la opción "Set Completo (Todas las piezas)"
    const assemblyRegex = /\b(socket|adaptador|base|tallo|stem|c[uú]pula|cap|shade|tapa|lid|cuerpo|body|brazo|arm|pierna|leg|torso|cabeza|head|soporte|difusor|parte\s*\d|part\s*\d|pieza\s*\d)\b/i;
    const isMultiPart = profiles.length > 1 && profiles.filter(p => assemblyRegex.test(p.title || '')).length >= 2;
    if (isMultiPart) {
      const totalGrams = Number(profiles.reduce((s, p) => s + p.grams, 0).toFixed(2));
      const totalHours = Number(profiles.reduce((s, p) => s + p.hours, 0).toFixed(3));
      const totalPlates = profiles.reduce((s, p) => s + p.plateCount, 0);
      profiles.unshift({
        id: 'full-assembly-combined',
        title: `⭐ Ensamble Completo (${profiles.length} piezas)`,
        name: 'Todas las piezas combinadas',
        grams: totalGrams,
        hours: totalHours,
        plateCount: totalPlates,
        isDefault: true,
        needAms: profiles.some(p => p.needAms),
        colorCount: Math.max(...profiles.map(p => p.colorCount || 1)),
        cover: profiles[0]?.cover || null
      });
    }

    if (!profiles.length) throw new Error('No stats.');
    return { json: { profiles } };
} catch (e) {
    throw new Error("Parse error: " + e.message);
}
